// The board's animal order is cat, dog, duck. Views refer to flash-resident data.
inline std::string_view GetSound(size_t index) {
    switch (index) {
        case 0:
            return {reinterpret_cast<const char*>(kCatOgg), sizeof(kCatOgg)};
        case 1:
            return {reinterpret_cast<const char*>(kDogOgg), sizeof(kDogOgg)};
        case 2:
            return {reinterpret_cast<const char*>(kDuckOgg), sizeof(kDuckOgg)};
        default:
            return {};
    }
}

